import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents banker rounding', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros formats euros', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(-5), '-€0.05');
  assert.equal(formatEuros(0), '€0.00');
});

test('parseEuros parses euro amounts', () => {
  const r1 = parseEuros('12');
  assert.equal(r1.ok, true);
  assert.equal(r1.value, 1200);

  const r2 = parseEuros('12.5');
  assert.equal(r2.ok, true);
  assert.equal(r2.value, 1250);

  const r3 = parseEuros('1,234.56');
  assert.equal(r3.ok, true);
  assert.equal(r3.value, 123456);
});

test('RATES constant defined', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const r = convert(10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 10850);
});

test('convert EUR to GBP', () => {
  const r = convert(10000, 'GBP');
  assert.equal(r.ok, true);
  assert.equal(r.value, 8425);
});

test('convert EUR to EUR', () => {
  const r = convert(10000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 10000);
});

test('convert with unknown currency', () => {
  const r = convert(10000, 'JPY');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_CURRENCY');
});

test('convert zero amount', () => {
  const r = convert(0, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('convert negative amount', () => {
  const r = convert(-10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, -10850);
});

test('convert large amount', () => {
  const r = convert(1000000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(typeof r.value, 'number');
  assert.equal(r.value > 1000000, true);
});

test('convert rounds correctly', () => {
  const r = convert(1, 'USD');
  assert.equal(r.ok, true);
  assert.equal(typeof r.value, 'number');
  assert.equal(r.value, 1);
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(-5, 'EUR'), '-€0.05');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(-5, 'GBP'), '-£0.05');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney with thousands separator', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
  assert.equal(formatMoney(1000000, 'GBP'), '£10,000.00');
});

test('formatMoney unknown currency', () => {
  const result = formatMoney(10000, 'JPY');
  assert.equal(result.includes('?'), true);
});

test('convert and format combined', () => {
  const converted = convert(10000, 'USD');
  assert.equal(converted.ok, true);
  const formatted = formatMoney(converted.value, 'USD');
  assert.equal(formatted, '$108.50');
});

test('convert EUR 6050 cents to USD', () => {
  const r = convert(6050, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 6564);
});

test('convert EUR 6050 cents to GBP', () => {
  const r = convert(6050, 'GBP');
  assert.equal(r.ok, true);
  assert.equal(r.value, 5098);
});

